import{_ as s,H as e,f as a,i as l}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"46 | 如何制作Docker镜像？","description":"","frontmatter":{},"headers":[{"level":2,"title":"Docker镜像的构建原理和方式","slug":"docker镜像的构建原理和方式","link":"#docker镜像的构建原理和方式","children":[{"level":3,"title":"通过 docker commit 命令构建镜像","slug":"通过-docker-commit-命令构建镜像","link":"#通过-docker-commit-命令构建镜像","children":[]},{"level":3,"title":"通过 Dockerfile 来构建镜像","slug":"通过-dockerfile-来构建镜像","link":"#通过-dockerfile-来构建镜像","children":[]},{"level":3,"title":"其他制作镜像方式","slug":"其他制作镜像方式","link":"#其他制作镜像方式","children":[]}]},{"level":2,"title":"Dockerfile指令介绍","slug":"dockerfile指令介绍","link":"#dockerfile指令介绍","children":[]},{"level":2,"title":"Dockerfile最佳实践","slug":"dockerfile最佳实践","link":"#dockerfile最佳实践","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"课后练习","slug":"课后练习","link":"#课后练习","children":[]}],"relativePath":"Go语言项目开发实战/46-如何制作Docker镜像？.md","filePath":"Go语言项目开发实战/46-如何制作Docker镜像？.md","lastUpdated":1779815754000}'),o={name:"Go语言项目开发实战/46-如何制作Docker镜像？.md"};function n(c,i,t,p,k,d){return e(),a("div",null,[...i[0]||(i[0]=[l(`<h1 id="_46-如何制作docker镜像" tabindex="-1">46 | 如何制作Docker镜像？ <a class="header-anchor" href="#_46-如何制作docker镜像" aria-label="Permalink to &quot;46 | 如何制作Docker镜像？&quot;">​</a></h1><p>你好，我是孔令飞。</p><p>要落地云原生架构，其中的一个核心点是通过容器来部署我们的应用。如果要使用容器来部署应用，那么制作应用的Docker镜像就是我们绕不开的关键一步。今天，我就来详细介绍下如何制作Docker镜像。</p><p>在这一讲中，我会先讲解下Docker镜像的构建原理和方式，然后介绍Dockerfile的指令，以及如何编写Dockerfile文件。最后，介绍下编写Dockerfile文件时要遵循的一些最佳实践。</p><h2 id="docker镜像的构建原理和方式" tabindex="-1">Docker镜像的构建原理和方式 <a class="header-anchor" href="#docker镜像的构建原理和方式" aria-label="Permalink to &quot;Docker镜像的构建原理和方式&quot;">​</a></h2><p>首先，我们来看下Docker镜像构建的原理和方式。</p><p>我们可以用多种方式来构建一个Docker镜像，最常用的有两种：</p><ul><li>通过 <code>docker commit</code> 命令，基于一个已存在的容器构建出镜像。</li><li>编写Dockerfile文件，并使用 <code>docker build</code> 命令来构建镜像。</li></ul><p>上面这两种方法中，镜像构建的底层原理是相同的，都是通过下面3个步骤来构建镜像：</p><ol><li>基于原镜像，启动一个Docker容器。</li><li>在容器中进行一些操作，例如执行命令、安装文件等。由这些操作产生的文件变更都会被记录在容器的存储层中。</li><li>将容器存储层的变更commit到新的镜像层中，并添加到原镜像上。</li></ol><p>下面，我们来具体讲解这两种构建Docker镜像的方式。</p><h3 id="通过-docker-commit-命令构建镜像" tabindex="-1">通过 <code>docker commit</code> 命令构建镜像 <a class="header-anchor" href="#通过-docker-commit-命令构建镜像" aria-label="Permalink to &quot;通过 \`docker commit\` 命令构建镜像&quot;">​</a></h3><p>我们可以通过 <code>docker commit</code> 来构建一个镜像，命令的格式为 <code>docker commit [选项] [&amp;lt;仓库名&gt;[:&amp;lt;标签&gt;]]</code>。</p><p>下图中，我们通过4个步骤构建了Docker镜像 <code>ccr.ccs.tencentyun.com/marmotedu/iam-apiserver-amd64:test</code>：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Go%E8%AF%AD%E8%A8%80%E9%A1%B9%E7%9B%AE%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/417216/23619b513ff043792c7374acf7781d11.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Go%E8%AF%AD%E8%A8%80%E9%A1%B9%E7%9B%AE%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/417216/23619b513ff043792c7374acf7781d11.png" alt="图片"></a></p><p>具体步骤如下：</p><ol><li>执行 <code>docker ps</code> 获取需要构建镜像的容器ID <code>48d1dbb89a7f</code>。</li><li>执行 <code>docker pause 48d1dbb89a7f</code> 暂停 <code>48d1dbb89a7f</code> 容器的运行。</li><li>执行 <code>docker commit 48d1dbb89a7f ccr.ccs.tencentyun.com/marmotedu/iam-apiserver-amd64:test</code>，基于容器ID <code>48d1dbb89a7f</code> 构建Docker镜像。</li><li>执行 <code>docker images ccr.ccs.tencentyun.com/marmotedu/iam-apiserver-amd64:test</code>，查看镜像是否成功构建。</li></ol><p>这种镜像构建方式通常用在下面两个场景中：</p><ul><li>构建临时的测试镜像；</li><li>容器被入侵后，使用 <code>docker commit</code>，基于被入侵的容器构建镜像，从而保留现场，方便以后追溯。</li></ul><p>除了这两种场景，我不建议你使用 <code>docker commit</code> 来构建生产现网环境的镜像。我这么说的主要原因有两个：</p><ul><li>使用 <code>docker commit</code> 构建的镜像包含了编译构建、安装软件，以及程序运行产生的大量无用文件，这会导致镜像体积很大，非常臃肿。</li><li>使用 <code>docker commit</code> 构建的镜像会丢失掉所有对该镜像的操作历史，无法还原镜像的构建过程，不利于镜像的维护。</li></ul><p>下面，我们再来看看如何使用 <code>Dockerfile</code> 来构建镜像。</p><h3 id="通过-dockerfile-来构建镜像" tabindex="-1">通过 <code>Dockerfile</code> 来构建镜像 <a class="header-anchor" href="#通过-dockerfile-来构建镜像" aria-label="Permalink to &quot;通过 \`Dockerfile\` 来构建镜像&quot;">​</a></h3><p>在实际开发中，使用 <code>Dockerfile</code> 来构建是最常用，也最标准的镜像构建方法。 <code>Dockerfile</code> 是Docker用来构建镜像的文本文件，里面包含了一系列用来构建镜像的指令。</p><p><code>docker build</code> 命令会读取 <code>Dockerfile</code> 的内容，并将 <code>Dockerfile</code> 的内容发送给Docker引擎，最终Docker引擎会解析 <code>Dockerfile</code> 中的每一条指令，构建出需要的镜像。</p><p><code>docker build</code> 的命令格式为 <code>docker build [OPTIONS] PATH | URL | -</code>。 <code>PATH</code>、 <code>URL</code>、 <code>-</code> 指出了构建镜像的上下文（context），context中包含了构建镜像需要的 <code>Dockerfile</code> 文件和其他文件。默认情况下，Docker构建引擎会查找context中名为 <code>Dockerfile</code> 的文件，但你可以通过 <code>-f, --file</code> 选项，手动指定 <code>Dockerfile</code> 文件。例如：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> $</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Dockerfile</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ccr.ccs.tencentyun.com/marmotedu/iam-apiserver-amd64:test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><p>使用Dockerfile构建镜像，本质上也是通过镜像创建容器，并在容器中执行相应的指令，然后停止容器，提交存储层的文件变更。和用 <code>docker commit</code> 构建镜像的方式相比，它有三个好处：</p><ul><li>Dockerfile 包含了镜像制作的完整操作流程，其他开发者可以通过 Dockerfile 了解并复现制作过程。</li><li>Dockerfile 中的每一条指令都会创建新的镜像层，这些镜像可以被 Docker Daemnon 缓存。再次制作镜像时，Docker 会尽量复用缓存的镜像层（using cache），而不是重新逐层构建，这样可以节省时间和磁盘空间。</li><li>Dockerfile 的操作流程可以通过 <code>docker image history [镜像名称]</code> 查询，方便开发者查看变更记录。</li></ul><p>这里，我们通过一个示例，来详细介绍下通过 <code>Dockerfile</code> 构建镜像的流程。</p><p><strong>首先，</strong> 我们需要编写一个 <code>Dockerfile</code> 文件。下面是iam-apiserver的 <a href="https://github.com/marmotedu/iam/blob/v1.0.8/build/docker/iam-apiserver/Dockerfile" target="_blank" rel="noreferrer">Dockerfile</a> 文件内容：</p><div class="language-dockerfile vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dockerfile</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> centos:centos8</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LABEL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> maintainer=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&amp;lt;colin404&amp;#64;foxmail.com&amp;gt;&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">RUN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ln -sf /usr/share/zoneinfo/Asia/Shanghai /etc/localtime</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">RUN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> echo </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Asia/Shanghai&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;gt; /etc/timezone</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WORKDIR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /opt/iam</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COPY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> iam-apiserver /opt/iam/bin/</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ENTRYPOINT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/opt/iam/bin/iam-apiserver&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>这里选择 <code>centos:centos8</code> 作为基础镜像，是因为 <code>centos:centos8</code> 镜像中包含了基本的排障工具，例如 <code>vi</code>、 <code>cat</code>、 <code>curl</code>、 <code>mkdir</code>、 <code>cp</code> 等工具。</p><p><strong>接着，</strong> 执行 <code>docker build</code> 命令来构建镜像：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Dockerfile</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ccr.ccs.tencentyun.com/marmotedu/iam-apiserver-amd64:test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><p>执行 <code>docker build</code> 后的构建流程为：</p><p><strong>第一步</strong>， <code>docker build</code> 会将context中的文件打包传给Docker daemon。如果context中有 <code>.dockerignore</code> 文件，则会从上传列表中删除满足 <code>.dockerignore</code> 规则的文件。</p><p>这里有个例外，如果 <code>.dockerignore</code> 文件中有 <code>.dockerignore</code> 或者 <code>Dockerfile</code>， <code>docker build</code> 命令在排除文件时会忽略掉这两个文件。如果指定了镜像的tag，还会对repository和tag进行验证。</p><p><strong>第二步</strong>， <code>docker build</code> 命令向Docker server发送HTTP请求，请求Docker server构建镜像，请求中包含了需要的context信息。</p><p><strong>第三步</strong>，Docker server接收到构建请求之后，会执行以下流程来构建镜像：</p><ol><li>创建一个临时目录，并将context中的文件解压到该目录下。</li><li>读取并解析Dockerfile，遍历其中的指令，根据命令类型分发到不同的模块去执行。</li><li>Docker构建引擎为每一条指令创建一个临时容器，在临时容器中执行指令，然后commit容器，生成一个新的镜像层。</li><li>最后，将所有指令构建出的镜像层合并，形成build的最后结果。最后一次commit生成的镜像ID就是最终的镜像ID。</li></ol><p>为了提高构建效率， <code>docker build</code> 默认会缓存已有的镜像层。如果构建镜像时发现某个镜像层已经被缓存，就会直接使用该缓存镜像，而不用重新构建。如果不希望使用缓存的镜像，可以在执行 <code>docker build</code> 命令时，指定 <code>--no-cache=true</code> 参数。</p><p>Docker匹配缓存镜像的规则为：遍历缓存中的基础镜像及其子镜像，检查这些镜像的构建指令是否和当前指令完全一致，如果不一样，则说明缓存不匹配。对于 <code>ADD</code>、 <code>COPY</code> 指令，还会根据文件的校验和（checksum）来判断添加到镜像中的文件是否相同，如果不相同，则说明缓存不匹配。</p><p>这里要注意，缓存匹配检查不会检查容器中的文件。比如，当使用 <code>RUN apt-get -y update</code> 命令更新了容器中的文件时，缓存策略并不会检查这些文件，来判断缓存是否匹配。</p><p>最后，我们可以通过 <code>docker history</code> 命令来查看镜像的构建历史，如下图所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Go%E8%AF%AD%E8%A8%80%E9%A1%B9%E7%9B%AE%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/417216/f32a0e2f90a36995a561747519897806.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Go%E8%AF%AD%E8%A8%80%E9%A1%B9%E7%9B%AE%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/417216/f32a0e2f90a36995a561747519897806.png" alt="图片"></a></p><h3 id="其他制作镜像方式" tabindex="-1">其他制作镜像方式 <a class="header-anchor" href="#其他制作镜像方式" aria-label="Permalink to &quot;其他制作镜像方式&quot;">​</a></h3><p>上面介绍的是两种最常用的镜像构建方式，还有一些其他的镜像创建方式，这里我简单介绍两种。</p><ol><li>通过 <code>docker save</code> 和 <code>docker load</code> 命令构建</li></ol><p><code>docker save</code> 用来将镜像保存为一个tar文件， <code>docker load</code> 用来将tar格式的镜像文件加载到当前机器上，例如：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 在 A 机器上执行，并将 nginx-v1.0.0.tar.gz 复制到 B 机器</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> save</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> gzip</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nginx-v1.0.0.tar.gz</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 在 B 机器上执行</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> load</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx-v1.0.0.tar.gz</span></span></code></pre></div><p>通过上面的命令，我们就在机器B上创建了 <code>nginx</code> 镜像。</p><ol start="2"><li>通过 <code>docker export</code> 和 <code>docker import</code> 命令构建</li></ol><p>我们先通过 <code>docker export</code> 保存镜像，再通过 <code>docker import</code> 加载镜像，具体命令如下：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 在 A 机器上执行，并将 nginx-v1.0.0.tar.gz 复制到 B 机器</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nginx-v1.0.0.tar.gz</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 在 B 机器上执行</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx:v1.0.0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx-v1.0.0.tar.gz</span></span></code></pre></div><p>通过 <code>docker export</code> 导出的镜像和通过 <code>docker save</code> 保存的镜像相比，会丢失掉所有的镜像构建历史。在实际生产环境中，我不建议你通过 <code>docker save</code> 和 <code>docker export</code> 这两种方式来创建镜像。我比较推荐的方式是：在A机器上将镜像push到镜像仓库，在B机器上从镜像仓库pull该镜像。</p><h2 id="dockerfile指令介绍" tabindex="-1">Dockerfile指令介绍 <a class="header-anchor" href="#dockerfile指令介绍" aria-label="Permalink to &quot;Dockerfile指令介绍&quot;">​</a></h2><p>上面，我介绍了一些与Docker镜像构建有关的基础知识。在实际生产环境中，我们标准的做法是通过Dockerfile来构建镜像，这就要求你会编写Dockerfile文件。接下来，我就详细介绍下如何编写Dockerfile文件。</p><p>Dockerfile指令的基本格式如下：</p><div class="language-dockerfile vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dockerfile</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Comment</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">INSTRUCTION arguments</span></span></code></pre></div><p><code>INSTRUCTION</code> 是指令，不区分大小写，但我的建议是指令都大写，这样可以与参数进行区分。Dockerfile中，以 <code>#</code> 开头的行是注释，而在其他位置出现的 <code>#</code> 会被当成参数，例如：</p><div class="language-dockerfile vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dockerfile</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Comment</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">RUN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> echo </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;hello world # dockerfile&#39;</span></span></code></pre></div><p>一个Dockerfile文件中包含了多条指令，这些指令可以分为5类。</p><ul><li>定义基础镜像的指令： <strong>FROM</strong>；</li><li>定义镜像维护者的指令： <strong>MAINTAINER</strong>（可选）；</li><li>定义镜像构建过程的指令： <strong>COPY</strong>、ADD、 <strong>RUN</strong>、USER、 <strong>WORKDIR</strong>、ARG、 <strong>ENV</strong>、VOLUME、 <strong>ONBUILD</strong>；</li><li>定义容器启动时执行命令的指令： <strong>CMD</strong>、 <strong>ENTRYPOINT</strong>；</li><li>其他指令：EXPOSE、HEALTHCHECK、STOPSIGNAL。</li></ul><p>其中，加粗的指令是编写Dockerfile时经常用到的指令，需要你重点了解下。我把这些常用Dockerfile指令的介绍放在了GitHub上，你可以看看这个 <a href="https://github.com/marmotedu/geekbang-go/blob/master/Dockerfile%E6%8C%87%E4%BB%A4%E8%AF%A6%E8%A7%A3.md" target="_blank" rel="noreferrer">Dockerfile指令详解</a>。</p><p>下面是一个Dockerfile示例：</p><div class="language-dockerfile vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dockerfile</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 第一行必须指定构建该镜像所基于的容器镜像</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> centos:centos8</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 维护者信息</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">MAINTAINER</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Lingfei Kong &amp;lt;colin404&amp;#64;foxmail.com&amp;gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 镜像的操作指令</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">RUN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ln -sf /usr/share/zoneinfo/Asia/Shanghai /etc/localtime</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">RUN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> echo </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Asia/Shanghai&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;gt; /etc/timezone</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WORKDIR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /opt/iam</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COPY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> iam-apiserver /opt/iam/bin/</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 容器启动时执行指令</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ENTRYPOINT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/opt/iam/bin/iam-apiserver&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>Docker会顺序解释并执行Dockerfile中的指令，并且第一条指令必须是 <code>FROM</code>， <code>FROM</code> 用来指定构建镜像的基础镜像。接下来，一般会指定镜像维护者的信息。后面是镜像操作的指令，最后会通过 <code>CMD</code> 或者 <code>ENTRYPOINT</code> 来指定容器启动的命令和参数。</p><h2 id="dockerfile最佳实践" tabindex="-1">Dockerfile最佳实践 <a class="header-anchor" href="#dockerfile最佳实践" aria-label="Permalink to &quot;Dockerfile最佳实践&quot;">​</a></h2><p>上面我介绍了Dockerfile的指令，但在编写Dockerfile时，只知道这些指令是不够的，还不能编写一个合格的Dockerfile。我们还需要遵循一些编写 Dockerfile的最佳实践。这里，我总结了一份编写 Dockerfile的最佳实践清单，你可以参考。</p><ol><li><p>建议所有的Dockerfile指令大写，这样做可以很好地跟在镜像内执行的指令区分开来。</p></li><li><p>在选择基础镜像时，尽量选择官方的镜像，并在满足要求的情况下，尽量选择体积小的镜像。目前，Linux镜像大小有以下关系： <code>busybox &amp;lt; debian &amp;lt; centos &amp;lt; ubuntu</code>。最好确保同一个项目中使用一个统一的基础镜像。如无特殊需求，可以选择使用 <code>debian:jessie</code> 或者 <code>alpine</code>。</p></li><li><p>在构建镜像时，删除不需要的文件，只安装需要的文件，保持镜像干净、轻量。</p></li><li><p>使用更少的层，把相关的内容放到一个层，并使用换行符进行分割。这样可以进一步减小镜像的体积，也方便查看镜像历史。</p></li><li><p>不要在Dockerfile中修改文件的权限。因为如果修改文件的权限，Docker在构建时会重新复制一份，这会导致镜像体积越来越大。</p></li><li><p>给镜像打上标签，标签可以帮助你理解镜像的功能，例如： <code>docker build -t=&quot;nginx:3.0-onbuild&quot;</code>。</p></li><li><p><code>FROM</code> 指令应该包含tag，例如使用 <code>FROM debian:jessie</code>，而不是 <code>FROM debian</code>。</p></li><li><p>充分利用缓存。Docker构建引擎会顺序执行Dockerfile中的指令，而且一旦缓存失效，后续命令将不能使用缓存。为了有效地利用缓存，需要尽量将所有的Dockerfile文件中相同的部分都放在前面，而将不同的部分放在后面。</p></li><li><p>优先使用 <code>COPY</code> 而非 <code>ADD</code> 指令。和 <code>ADD</code> 相比， <code>COPY</code> 功能简单，而且也够用。 <code>ADD</code> 可变的行为会导致该指令的行为不清晰，不利于后期维护和理解。</p></li><li><p>推荐将 <code>CMD</code> 和 <code>ENTRYPOINT</code> 指令结合使用，使用execl格式的 <code>ENTRYPOINT</code> 指令设置固定的默认命令和参数，然后使用 <code>CMD</code> 指令设置可变的参数。</p></li><li><p>尽量使用Dockerfile共享镜像。通过共享Dockerfile，可以使开发者明确知道Docker镜像的构建过程，并且可以将Dockerfile文件加入版本控制，跟踪起来。</p></li><li><p>使用 <code>.dockerignore</code> 忽略构建镜像时非必需的文件。忽略无用的文件，可以提高构建速度。</p></li><li><p>使用多阶段构建。多阶段构建可以大幅减小最终镜像的体积。例如， <code>COPY</code> 指令中可能包含一些安装包，安装完成之后这些内容就废弃掉。下面是一个简单的多阶段构建示例：</p></li></ol><div class="language-dockerfile vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dockerfile</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> golang:1.11-alpine </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> build</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 安装依赖包</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">RUN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> go get github.com/golang/mock/mockgen</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 复制源码并执行build，此处当文件有变化会产生新的一层镜像层</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COPY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> . /go/src/iam/</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">RUN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> go build -o /bin/iam</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 缩小到一层镜像</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> busybox</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COPY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> --from=build /bin/iam /bin/iam</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ENTRYPOINT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/bin/iam&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CMD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;--help&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>如果你想使用Docker容器来部署应用，那么就需要制作Docker镜像。今天，我介绍了如何制作Docker镜像。</p><p>你可以使用这两种方式来构建Docker镜像：</p><ul><li>通过 <code>docker commit</code> 命令，基于一个已存在的容器构建出镜像。</li><li>通过编写Dockerfile文件，并使用 <code>docker build</code> 命令来构建镜像。</li></ul><p>这两种方法中，镜像构建的底层原理是相同的：</p><ol><li><p>基于原镜像启动一个Docker容器。</p></li><li><p>在容器中进行一些操作，例如执行命令、安装文件等，由这些操作产生的文件变更都会被记录在容器的存储层中。</p></li><li><p>将容器存储层的变更commit到新的镜像层中，并添加到原镜像上。</p></li></ol><p>此外，我们还可以使用 <code>docker save</code> / <code>docker load</code> 和 <code>docker export</code> / <code>docker import</code> 来复制Docker镜像。</p><p>在实际生产环境中，我们标准的做法是通过Dockerfile来构建镜像。使用Dockerfile构建镜像，就需要你编写Dockerfile文件。Dockerfile支持多个指令，这些指令可以分为5类，对指令的具体介绍你可以再返回复习一遍。</p><p>另外，我们在构建Docker镜像时，也要遵循一些最佳实践，具体你可以参考我给你总结的最佳实践清单。</p><h2 id="课后练习" tabindex="-1">课后练习 <a class="header-anchor" href="#课后练习" aria-label="Permalink to &quot;课后练习&quot;">​</a></h2><ol><li><p>思考下，为什么在编写Dockerfile时，“把相关的内容放到一个层，使用换行符 <code>\\</code> 进行分割”可以减小镜像的体积？</p></li><li><p>尝试一下，为你正在开发的应用编写Dockerfile文件，并成功构建出Docker镜像。</p></li></ol><p>欢迎你在留言区与我交流讨论，我们下一讲见。</p>`,84)])])}const g=s(o,[["render",n]]);export{h as __pageData,g as default};
